#!/usr/bin/env node
/**
 * Check the architecture decision records.
 *
 * An ADR that has lost its **alternatives** is a decision without a
 * rationale, and a decision without a rationale is a decision somebody
 * will quietly reverse. So each record must have its context, its
 * decision, the alternatives that were considered, and its
 * consequences — and a **status**.
 *
 * The index is regenerated by this script, so it cannot drift from the
 * records.
 *
 * Usage:
 *   node scripts/check-adrs.mjs
 *   node scripts/check-adrs.mjs --index   rewrite the index
 */
import { existsSync } from 'node:fs';
import { readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';

const ROOT = process.cwd();
const DIR = path.join(ROOT, 'docs/adr');
const INDEX = path.join(DIR, 'README.md');

/** The sections every record must have. */
const SECTIONS = ['## Context', '## Decision', '## Alternatives', '## Consequences'];

/** The statuses a record may have. */
const STATUSES = ['accepted', 'proposed', 'deprecated', 'superseded'];

async function main() {
  if (!existsSync(DIR)) {
    console.error('there is no docs/adr directory.');
    process.exit(1);
  }

  const names = (await readdir(DIR)).filter((name) => name.endsWith('.md')).sort();
  const records = [];

  for (const name of names) {
    if (name === 'README.md') continue;
    const text = await readFile(path.join(DIR, name), 'utf8');

    const title = /^# (\d+)\. (.+)$/m.exec(text);
    if (!title) {
      console.error(`${name}: the title is not "# <number>. <decision>"`);
      process.exit(1);
    }

    const status = /\*\*Status:\*\* (\w+)/.exec(text);
    if (!status) {
      console.error(`${name}: it has no status`);
      process.exit(1);
    }
    if (!STATUSES.includes(status[1])) {
      console.error(`${name}: the status "${status[1]}" is not one of ${STATUSES.join(', ')}`);
      process.exit(1);
    }

    for (const section of SECTIONS) {
      if (!text.includes(section)) {
        console.error(`${name}: it has no "${section}" section`);
        process.exit(1);
      }
    }

    // The alternatives have to say something: a heading with nothing
    // under it is not an alternative.
    const alternatives = text.split('## Alternatives')[1]?.split('##')[0] ?? '';
    if (alternatives.trim().length < 40) {
      console.error(`${name}: the alternatives say nothing`);
      process.exit(1);
    }

    records.push({
      file: name,
      number: Number(title[1]),
      title: title[2],
      status: status[1],
    });
  }

  // The numbers are a sequence with no gaps.
  records.sort((a, b) => a.number - b.number);
  records.forEach((record, index) => {
    if (record.number !== index + 1) {
      console.error(`the records are not numbered in sequence: ${record.file} is ${record.number}`);
      process.exit(1);
    }
  });

  const index = [
    '# The architecture decision records',
    '',
    'Each record states a decision, the alternatives that were considered, and the',
    'reasoning. A decision without a rationale is a decision somebody will quietly',
    'reverse, so the alternatives and the consequences are the parts that matter.',
    '',
    'The roadmap\'s "Locked Decisions" section is the summary; these are the whole',
    'reasoning.',
    '',
    '| # | Decision | Status |',
    '| --- | --- | --- |',
    ...records.map(
      (record) =>
        `| ${record.number} | [${record.title}](./${record.file}) | ${record.status} |`,
    ),
    '',
  ].join('\n');

  if (process.argv.includes('--index')) {
    await writeFile(INDEX, index, 'utf8');
    console.log(`the index is written: ${records.length} records`);
    return;
  }

  const current = existsSync(INDEX) ? await readFile(INDEX, 'utf8') : '';
  if (current !== index) {
    console.error('the index does not match the records. Run:\n  node scripts/check-adrs.mjs --index');
    process.exit(1);
  }

  console.log(`the ADRs: ${records.length}, all with a status, a context, a decision, alternatives and consequences`);
  console.log('OK: the decision records are well formed.');
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
